// Group stickers by category
export const STICKERS_BY_CATEGORY = ANIMATED_STICKERS.reduce((acc, sticker) => {
  if (!acc[sticker.category]) {
    acc[sticker.category] = []
  }
  acc[sticker.category].push(sticker)
  return acc
}, {} as Record<string, typeof ANIMATED_STICKERS>)

// Get all categories
export const STICKER_CATEGORIES = Object.keys(STICKERS_BY_CATEGORY)

// Get stickers for a specific category
export function getStickersByCategory(category: string) {
  return STICKERS_BY_CATEGORY[category] || []
}

// Get total sticker count
export function getTotalStickerCount(): number {
  return ANIMATED_STICKERS.length
}
